namespace Touchline {
public static class PlayerAdvice {
 public static string Warnings(Game g,Club c){var ps=g.Squad(c.Id).ToArray();var notes=new List<string>();if(!ps.Any(p=>p.Type=="门将"&&p.Injury==0))notes.Add("没有健康门将，门将位置将受到错位惩罚。");if(ps.Count(p=>p.Injury==0)<10)notes.Add("健康球员不足10人，将无法正常开赛。");
  foreach(string type in Rules.Types){int n=ps.Count(p=>p.Type==type&&p.Injury==0);if(n<(type=="门将"?2:5))notes.Add(type+"健康人数："+n+"，替补深度不足。");}
  foreach(string type in new[]{"前锋","中场","后卫"})foreach(int foot in new[]{0,1,2})if(ps.Count(p=>p.Type==type&&p.Foot==foot&&p.Injury==0)<2)notes.Add(type+" / "+new[]{"双足","左足","右足"}[foot]+"：同类型惯用脚替补不足。");
  var tired=ps.Where(p=>p.Fatigue>=6).Select(p=>p.Name+" "+p.Fatigue+"%").ToArray();if(tired.Length>0)notes.Add("疲劳较高："+string.Join("、",tired));
  int games=g.Fixtures.Count(f=>!f.Played&&f.Week==g.Week&&(f.Home==c.Id||f.Away==c.Id));if(games>=3)notes.Add("本周还有"+games+"场比赛，建议安排轮换。");double wages=ps.Sum(p=>p.Value);if(c.Funds<wages)notes.Add("当前资金不足以支付全队季工资，缺口："+(wages-c.Funds).ToString("F2"));return notes.Count==0?"未发现明显阵容或预算风险。":string.Join("\r\n",notes.ToArray());
 }
}
public static class CompetitionStatistics {
 public static readonly string[] Options=new[]{"联赛1","联赛2","联赛3","一级杯赛 · 联赛1","一级杯赛 · 联赛2","一级杯赛 · 联赛3","二级杯赛 · 联赛1","二级杯赛 · 联赛2","二级杯赛 · 联赛3","欧冠","欧联"};
 public static string Competition(string option){return option.StartsWith("联赛")?"联赛":option.Split(' ')[0];}
 public static IEnumerable<Player> Players(Game g,string option,int metric){string comp=Competition(option);int league=option.Contains("联赛")?int.Parse(option.Substring(option.Length-1)):0;return g.Players.Where(p=>p.Stats.ContainsKey(comp)&&(league==0||p.ClubId!=""&&g.Club(p.ClubId).League==league)).OrderByDescending(p=>p.Stats[comp][metric]);}
}
