 DataGridView ownMatchPlayers,opponentMatchPlayers;TextBox opponentDecisionBox;
 void MatchInformationPanel(Control target){var layout=new TableLayoutPanel{Dock=DockStyle.Fill,RowCount=6,ColumnCount=1,BackColor=Bg};layout.RowStyles.Add(new RowStyle(SizeType.Absolute,26));layout.RowStyles.Add(new RowStyle(SizeType.Percent,50));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,26));layout.RowStyles.Add(new RowStyle(SizeType.Percent,50));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,28));layout.RowStyles.Add(new RowStyle(SizeType.Absolute,116));target.Controls.Add(layout);
  var f=game.Fixtures.First(x=>x.Id==game.Live.FixtureId);string foe=f.Home==game.PlayerClubId?f.Away:f.Home;var ownTitle=Label("己方 · "+game.Club(game.PlayerClubId).Name,10,Accent);ownTitle.Margin=new Padding(3,0,0,0);ownTitle.AutoSize=false;ownTitle.Dock=DockStyle.Fill;ownTitle.TextAlign=ContentAlignment.MiddleLeft;var otherTitle=Label("对手 · "+game.Club(foe).Name,10,Accent);otherTitle.Margin=new Padding(3,0,0,0);otherTitle.AutoSize=false;otherTitle.Dock=DockStyle.Fill;otherTitle.TextAlign=ContentAlignment.MiddleLeft;layout.Controls.Add(ownTitle,0,0);layout.Controls.Add(otherTitle,0,2);
