 }
 DataGridView MatchPlayerGrid(){var grid=Grid();grid.Font=new Font("Microsoft YaHei UI",9);grid.ColumnHeadersDefaultCellStyle.Font=new Font("Microsoft YaHei UI",8);grid.RowTemplate.Height=20;grid.ColumnHeadersHeight=26;Columns(grid,"球员","位置","身价","红","绿","蓝","黑","射／扑","疲劳","分钟");grid.AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill;for(int i=0;i<grid.Columns.Count;i++){grid.Columns[i].MinimumWidth=i==0?70:i==1?66:i==2?44:i==7?48:40;grid.Columns[i].FillWeight=i==0?90:i==1?80:47;}return grid;}
 void RefreshMatchInformation(Game g,LiveMatch m){if(ownMatchPlayers==null||ownMatchPlayers.IsDisposed||m==null)return;var f=g.Fixtures.First(x=>x.Id==m.FixtureId);bool ownHome=f.Home==g.PlayerClubId;FillMatchPlayers(ownMatchPlayers,g,m,ownHome);FillMatchPlayers(opponentMatchPlayers,g,m,!ownHome);if(opponentDecisionBox!=null&&!opponentDecisionBox.IsDisposed){string content=OpponentDecisions.Text(g,f);if(opponentDecisionBox.Text!=content){opponentDecisionBox.Text=content;opponentDecisionBox.SelectionStart=0;opponentDecisionBox.ScrollToCaret();}}}
 void FillMatchPlayers(DataGridView grid,Game g,LiveMatch m,bool home){grid.Rows.Clear();var f=g.Fixtures.First(x=>x.Id==m.FixtureId);var club=g.Club(home?f.Home:f.Away);var foe=g.Club(home?f.Away:f.Home);var ids=home?m.HomeLineup:m.AwayLineup;string tactic=home?m.HomeTactic:m.AwayTactic;var ps=ids.Select(id=>g.Players.First(p=>p.Id==id)).ToArray();string star=ps.OrderByDescending(p=>p.Value).First().Id;
  for(int slot=0;slot<10;slot++){var p=ps[slot];int state;if(!m.Status.TryGetValue(p.Id,out state))state=Rules.Round((p.Favor+7)/2.0);var a=Football.Weight(p,slot,club.Philosophy,tactic,foe.Philosophy,state,home&&!f.Neutral,p.Id==star);int minutes=m.Minutes!=null&&m.Minutes.ContainsKey(p.Id)?m.Minutes[p.Id]:0;int row=grid.Rows.Add(p.Name,Rules.Slots[slot],p.Value.ToString("F1"),a.R.ToString("F1"),a.G.ToString("F1"),a.B.ToString("F1"),p.Black.ToString("F1"),a.S.ToString("F1"),p.Fatigue+"%",minutes);grid.Rows[row].Cells[0].Style.BackColor=RoleColor(p.Type);grid.Rows[row].Cells[0].Style.ForeColor=p.Type=="门将"?Color.White:Color.Black;foreach(DataGridViewCell cell in grid.Rows[row].Cells)cell.ToolTipText=L10n.T("当前常驻加权能力（不含角球瞬时效果）；尚未出场时为状态期望估算。")+"\r\n"+p.Name+" / "+p.Type+" / "+Rules.Slots[slot];}
 }
 internal void ShowMatchReview(Fixture f){using(var dialog=new Form{Text=L10n.T("比赛复盘"),Size=new Size(1060,760),StartPosition=FormStartPosition.CenterParent,BackColor=Bg,ForeColor=White}){
  var split=new SplitContainer{Dock=DockStyle.Fill,Orientation=Orientation.Horizontal,Size=new Size(1020,700),SplitterDistance=280};dialog.Controls.Add(split);var grid=Grid();Columns(grid,"球队","路线","球权","攻防对拼","成功推进","射门","射正");split.Panel1.Controls.Add(grid);if(f.Review!=null)for(int side=0;side<2;side++)for(int lane=0;lane<3;lane++){int i=side*3+lane;grid.Rows.Add(game.Club(side==0?f.Home:f.Away).Name,new[]{"左","中","右"}[lane],f.Review.Possessions[i],f.Review.Duels[i],f.Review.DuelsWon[i],f.Review.Shots[i],f.Review.OnTarget[i]);}
  var text=new TextBox{Dock=DockStyle.Fill,Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Both,WordWrap=true,BackColor=Card,ForeColor=White,Font=Font};string summary=f.Review==null?"该场比赛没有分路复盘数据。":L10n.T("角球触发（主／客）：")+f.Review.Corners[0]+" / "+f.Review.Corners[1]+"\r\n"+L10n.T("战术犯规阻止射正（主／客）：")+f.Review.Fouls[0]+" / "+f.Review.Fouls[1];text.Text=L10n.T(summary)+"\r\n\r\n"+string.Join("\r\n",f.Commentary.Select(L10n.T).ToArray());split.Panel2.Controls.Add(text);L10n.Watch(dialog);dialog.ShowDialog(this);}
 }
 internal double? AskTransferFee(Player p){var buyer=game.Club(game.PlayerClubId);using(var dialog=new Form{Text=L10n.T("转会预算预览"),Size=new Size(610,340),StartPosition=FormStartPosition.CenterParent,BackColor=Bg,ForeColor=White,Font=Font}){var title=Label(p.Name+" · "+L10n.T("报价金额"),12);title.SetBounds(20,16,550,28);dialog.Controls.Add(title);var amount=new NumericUpDown{Minimum=0,Maximum=100000000,DecimalPlaces=2,Value=(decimal)Math.Min(100000000,Transfers.Fee(game,p,false)),Enabled=p.ClubId!="",Width=300,Location=new Point(20,55)};dialog.Controls.Add(amount);var info=new Label{Location=new Point(20,96),Size=new Size(555,130),ForeColor=White};dialog.Controls.Add(info);var ok=Button("提出报价",()=>dialog.DialogResult=DialogResult.OK);ok.SetBounds(395,240,170,42);dialog.Controls.Add(ok);Action draw=()=>{double fee=(double)amount.Value;double after=buyer.Funds-fee,wages=game.Squad(buyer.Id).Sum(x=>x.Value)+p.Value;bool valid=p.ClubId!=buyer.Id&&Transfers.Affordable(game,p,buyer,fee)&&(p.ClubId==""||fee+1e-7>=Transfers.Fee(game,p,false));info.Text=L10n.T("转会后资金：")+after.ToString("F2")+"\r\n"+L10n.T("转入后全队季工资：")+wages.ToString("F2")+"\r\n"+L10n.T("工资结余：")+(after-wages).ToString("F2")+"\r\n"+L10n.T(valid?"预算足够，仍须卖方及球员同意。":"资金不足或报价低于最低费用，不能提交。");info.ForeColor=valid?White:Color.Salmon;ok.Enabled=valid;};amount.ValueChanged+=(s,e)=>draw();draw();L10n.Watch(dialog);return dialog.ShowDialog(this)==DialogResult.OK?(double?)amount.Value:null;}}
 void StatsPageSeparated(){var actions=Actions();var comp=new DarkComboBox{Width=245};comp.Items.AddRange(CompetitionStatistics.Options);comp.SelectedIndex=game.Club(game.PlayerClubId).League-1;actions.Controls.Add(comp);var metric=new DarkComboBox{Width=180};metric.Items.AddRange(new object[]{"进球","助攻","绝佳传球","抢夺球权","成功抢断","成功扑救"});metric.SelectedIndex=0;actions.Controls.Add(metric);var grid=Grid();body.Controls.Add(grid);grid.BringToFront();Columns(grid,"名次","球员","俱乐部","联赛","位置","数据");Action draw=()=>{grid.Rows.Clear();string option=Convert.ToString(comp.SelectedItem),competition=CompetitionStatistics.Competition(option);int index=metric.SelectedIndex,n=0,rank=0;double previous=double.NaN;foreach(var p in CompetitionStatistics.Players(game,option,index)){n++;double value=p.Stats[competition][index];if(value!=previous)rank=n;previous=value;grid.Rows.Add(rank,p.Name,p.ClubId==""?"自由球员":game.Club(p.ClubId).Name,p.ClubId==""?0:game.Club(p.ClubId).League,p.Type,value);}};comp.SelectedIndexChanged+=(s,e)=>draw();metric.SelectedIndexChanged+=(s,e)=>draw();draw();}
}
